<?php
namespace App\Modules\Scheduling\Actions;
use App\Modules\Scheduling\Models\{Appointment,AppointmentEvent}; use App\Modules\Scheduling\Services\SchedulingAudit; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class CancelAppointment { public function __construct(private SchedulingAudit $audit){} public function execute(Appointment $appointment,string $token,?int $actor=null): Appointment { return DB::transaction(function()use($appointment,$token,$actor){$item=Appointment::query()->lockForUpdate()->findOrFail($appointment->id); if(!$actor&&!hash_equals($item->cancellation_token_hash,hash('sha256',$token)))throw ValidationException::withMessages(['token'=>'Link de cancelamento inválido.']); if($item->status!=='cancelled'){$item->update(['status'=>'cancelled','cancelled_at'=>now()]); AppointmentEvent::query()->create(['appointment_id'=>$item->id,'event_type'=>'cancelled','metadata'=>[],'actor_type'=>$actor?'user':'guest','actor_id'=>$actor,'created_at'=>now()]);$this->audit->record('appointment.cancelled',$item->id,$actor);}return $item;},3); } }
